ALTER FUNCTION nearyou.acquire_cutover_lease(text,text) OWNER TO nearyou_cutover_policy_owner;
ALTER FUNCTION nearyou.renew_cutover_lease(text,text,bigint) OWNER TO nearyou_cutover_policy_owner;
