ALTER FUNCTION nearyou.record_cutover_operation(text,text,text,bigint,jsonb) OWNER TO nearyou_cutover_policy_owner;
ALTER FUNCTION nearyou.transition_cutover(text,text,bigint,text,bigint,text) OWNER TO nearyou_cutover_policy_owner;
ALTER FUNCTION nearyou.begin_rollback_capture(text,text,bigint,text,bigint,text) OWNER TO nearyou_cutover_policy_owner;
