REVOKE ALL ON FUNCTION nearyou.current_cutover_time(),nearyou.acquire_cutover_lease(text,text),nearyou.renew_cutover_lease(text,text,bigint),nearyou.initialize_cutover_snapshot(text,text,bigint,bigint),nearyou.record_cutover_operation(text,text,text,bigint,jsonb),nearyou.transition_cutover(text,text,bigint,text,bigint,text),nearyou.begin_rollback_capture(text,text,bigint,text,bigint,text),nearyou.refence_rollback(text,text,bigint,bigint),nearyou.record_rollback_manifest(text,text,bigint,text,jsonb),nearyou.transition_rollback(text,text,bigint,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nearyou.current_cutover_time(),nearyou.acquire_cutover_lease(text,text),nearyou.renew_cutover_lease(text,text,bigint),nearyou.initialize_cutover_snapshot(text,text,bigint,bigint),nearyou.record_cutover_operation(text,text,text,bigint,jsonb),nearyou.transition_cutover(text,text,bigint,text,bigint,text),nearyou.begin_rollback_capture(text,text,bigint,text,bigint,text),nearyou.refence_rollback(text,text,bigint,bigint),nearyou.record_rollback_manifest(text,text,bigint,text,jsonb),nearyou.transition_rollback(text,text,bigint,text,jsonb) TO nearyou_cutover_runner;
COMMIT;
